ARISTON-NUOS-PRIMO-HC-240", "aliases": [], "prix_unitaire_ht": null, "caracteristiques": {"volume_l": 240.0, "profil": "XL", "efficacite": 118, "cop": 2.86, "type_ballon": "monobloc", "code_article": "3069654", "classe_energetique": "A", "prix_a_renseigner": true}, "description": "Ariston · Chauffe-eau thermodynamique monobloc · 240 L · profil XL · ηwh 118 % · COP 2,86 · classe A."}, {"nom": "Chauffe-eau thermodynamique split Ariston NUOS SPLIT INVERTER WIFI 150 (3069761), 152 L, R513a, COP 3,34 à +7 °C, profil L, ηwh 134 %", "marque": "Ariston", "reference": "CET-ARISTON-NUOS-SPLIT-INV-150", "aliases": [], "prix_unitaire_ht": 2735.0, "caracteristiques": {"volume_l": 152.0, "profil": "L", "efficacite": 134, "cop": 3.34, "fluide": "R513a", "type_ballon": "split", "code_article": "3069761", "gamme": "Haut de gamme", "classe_energetique": "A+"}, "description": "Ariston · Chauffe-eau thermodynamique split · 152 L · profil L · ηwh 134 % · COP 3,34 · R513a · classe A+ · Haut de gamme."}, {"nom": "Chauffe-eau thermodynamique split Ariston NUOS SPLIT INVERTER WIFI 200 (3069762), 203 L, R513a, COP 3,26 à +7 °C, profil L, ηwh 134 %", "marque": "Ariston", "reference": "CET-ARISTON-NUOS-SPLIT-INV-200", "aliases": [], "prix_unitaire_ht": 2795.0, "caracteristiques": {"volume_l": 203.0, "profil": "L", "efficacite": 134, "cop": 3.26, "fluide": "R513a", "type_ballon": "split", "code_article": "3069762", "gamme": "Haut de gamme", "classe_energetique": "A+"}, "description": "Ariston · Chauffe-eau thermodynamique split · 203 L · profil L · ηwh 134 % · COP 3,26 · R513a · classe A+ · Haut de gamme."}, {"nom": "Chauffe-eau thermodynamique split Ariston NUOS SPLIT INVERTER WIFI 270 (3069763), 273 L, R513a, COP 3,55 à +7 °C, profil XL, ηwh 144 %", "marque": "Ariston", "reference": "CET-ARISTON-NUOS-SPLIT-INV-270", "aliases": [], "prix_unitaire_ht": 3050.0, "caracteristiques": {"volume_l": 273.0, "profil": "XL", "efficacite": 144, "cop": 3.55, "fluide": "R513a", "type_ballon": "split", "code_article": "3069763", "gamme": "Haut de gamme", "classe_energetique": "A+"}, "description": "Ariston · Chauffe-eau thermodynamique split · 273 L · profil XL · ηwh 144 % · COP 3,55 · R513a · classe A+ · Haut de gamme."}]$produits$::jsonb) LOOP
    v_aliases := ARRAY(SELECT jsonb_array_elements_text(p->'aliases'));

    SELECT id INTO v_id
    FROM catalogue_produits
    WHERE categorie = 'ballon_thermodynamique'
      AND (reference = p->>'reference' OR reference = ANY(v_aliases))
    ORDER BY (reference = p->>'reference') DESC, actif DESC, created_at NULLS LAST
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO catalogue_produits (
        entreprise_id, categorie, nom, marque, reference, description, caracteristiques,
        prix_unitaire_ht, unite, tva_taux, eligible_mpr, eligible_cee, fiche_cee, actif,
        public_cible, catalogue_groupe, forfait_pose_ht, forfait_evacuation_ht
      ) VALUES (
        v_entreprise, 'ballon_thermodynamique', p->>'nom', p->>'marque', p->>'reference', p->>'description',
        p->'caracteristiques' || '{"fiche_cee":"BAR-TH-148"}'::jsonb,
        COALESCE(NULLIF(p->>'prix_unitaire_ht','')::numeric, 0),
        'unite', 5.5, false, true, 'BAR-TH-148', true, 'particulier', 'particulier', 0, 0
      );
      v_ajoutes := v_ajoutes + 1;
    ELSE
      UPDATE catalogue_produits SET
        nom = p->>'nom',
        marque = p->>'marque',
        reference = p->>'reference',
        description = CASE
          WHEN COALESCE(btrim(description), '') = ''
            OR description = nom
            OR description = p->>'nom'
          THEN p->>'description'
          ELSE description
        END,
        caracteristiques = (COALESCE(caracteristiques, '{}'::jsonb) - 'prix_a_renseigner'::text)
                           || ((p->'caracteristiques') - 'prix_a_renseigner'::text)
                           || CASE WHEN array_length(v_aliases, 1) > 0 AND reference = ANY(v_aliases)
                                THEN jsonb_build_object('ancienne_reference', reference)
                                ELSE '{}'::jsonb END,
        prix_unitaire_ht = COALESCE(NULLIF(p->>'prix_unitaire_ht','')::numeric, prix_unitaire_ht),
        tva_taux = 5.5,
        fiche_cee = 'BAR-TH-148',
        eligible_cee = true,
        eligible_mpr = false,
        actif = true
      WHERE id = v_id;
      v_maj := v_maj + 1;
    END IF;
    v_id := NULL;
  END LOOP;

  UPDATE catalogue_produits
  SET caracteristiques = CASE
    WHEN COALESCE(prix_unitaire_ht, 0) > 0 THEN caracteristiques - 'prix_a_renseigner'::text
    ELSE caracteristiques || '{"prix_a_renseigner": true}'::jsonb
